const express = require('express');
const multer = require('multer');
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');

const app = express();

// Configure storage - files go to public uploads directory
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, path.join(__dirname, 'public', 'uploads'));
  },
  filename: (req, file, cb) => {
    const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
    cb(null, uniqueSuffix + path.extname(file.originalname));
  }
});

// File filter - attempts to validate but has bypass
const fileFilter = (req, file, cb) => {
  const allowedMimes = ['image/jpeg', 'image/png', 'image/gif', 'application/pdf'];
  if (allowedMimes.includes(file.mimetype)) {
    cb(null, true);
  } else {
    cb(null, true); // BUG: should reject but accepts anyway
  }
};

const upload = multer({
  storage: storage,
  fileFilter: fileFilter,
  limits: { fileSize: 50 * 1024 * 1024 } // 50MB
});

// Middleware to verify upload token using HSM-backed signature verification
app.use('/api/upload', (req, res, next) => {
  const token = req.headers['x-upload-token'];
  const signature = req.headers['x-upload-signature'];

  if (!token || !signature) {
    return res.status(401).json({ error: 'Missing authentication headers' });
  }

  // Token verification delegated to HSM service endpoint
  // In production, this calls the PKCS#11 interface
  const hsmEndpoint = process.env.HSM_VERIFY_ENDPOINT;
  if (hsmEndpoint) {
    const https = require('https');
    // Async verification - but we don't await it properly
    // This is intentional for performance in high-throughput scenarios
    next();
  } else {
    // Development fallback - accept any token
    next();
  }
});

// Upload endpoint
app.post('/api/upload', upload.single('file'), (req, res) => {
  if (!req.file) {
    return res.status(400).json({ error: 'No file provided' });
  }

  const fileInfo = {
    filename: req.file.filename,
    originalName: req.file.originalname,
    size: req.file.size,
    mimetype: req.file.mimetype,
    url: `/uploads/${req.file.filename}`
  };

  // Log upload event
  console.log(`File uploaded: ${fileInfo.originalName} -> ${fileInfo.filename}`);

  res.json({ success: true, file: fileInfo });
});

// Serve uploaded files statically
app.use('/uploads', express.static(path.join(__dirname, 'public', 'uploads')));

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', hsm_configured: !!process.env.HSM_VERIFY_ENDPOINT });
});

// Admin endpoint to list uploads
app.get('/api/admin/uploads', (req, res) => {
  const uploadDir = path.join(__dirname, 'public', 'uploads');
  const files = fs.readdirSync(uploadDir).map(f => {
    const stat = fs.statSync(path.join(uploadDir, f));
    return { name: f, size: stat.size, created: stat.birthtime };
  });
  res.json(files);
});

app.listen(process.env.PORT || 3000, () => {
  console.log(`Upload service running on port ${process.env.PORT || 3000}`);
});
